mapper.select:
SELECT share.account_id, share.account_name, COUNT(DISTINCT share.order_id) AS order_count,
       IFNULL(SUM(share.share_amount), 0) AS share_amount
FROM dms_order_company_share share
INNER JOIN dms_shop_order scoped_order ON scoped_order.id = share.order_id
WHERE COALESCE(scoped_order.tenant_id, 1) = #{tenantId}

    AND share.create_time >= #{startTime}


    AND share.create_time < #{endTime}

GROUP BY share.account_id, share.account_name
ORDER BY share_amount DESC

mapper.insert:
INSERT INTO dms_order_company_share (order_id, order_no, account_id, account_name, share_rate, share_amount, remark)
SELECT #{share.orderId}, #{share.orderNo}, #{share.accountId}, #{share.accountName}, #{share.shareRate},
       #{share.shareAmount}, #{share.remark}
FROM dms_shop_order scoped_order
WHERE scoped_order.id = #{share.orderId}
  AND COALESCE(scoped_order.tenant_id, 1) = #{tenantId}
